def notes_list(date_from=None, date_to=None, tag=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0486000" if __import__("os").path.isdir("./environment_mix/0486000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_date(s, field_name):
        if s is None:
            return None
        if not isinstance(s, str):
            return ("__bad__", _err("VALIDATION_ERROR", f"{field_name} must be a string in YYYY-MM-DD format.", field=field_name))
        try:
            return datetime.date.fromisoformat(s)
        except Exception:
            return ("__bad__", _err("VALIDATION_ERROR", f"{field_name} must be a valid YYYY-MM-DD date string.", field=field_name))

    t0 = time.time()
    status = "ok"
    error_obj = None

    # ---- Validate inputs first ----
    df = _parse_date(date_from, "date_from")
    if isinstance(df, tuple) and df and df[0] == "__bad__":
        status = "error"
        error_obj = df[1]
    dt = None
    if error_obj is None:
        dt = _parse_date(date_to, "date_to")
        if isinstance(dt, tuple) and dt and dt[0] == "__bad__":
            status = "error"
            error_obj = dt[1]

    if error_obj is None and df is not None and dt is not None and df > dt:
        status = "error"
        error_obj = _err("VALIDATION_ERROR", "date_from cannot be later than date_to.", field="date_from")

    if error_obj is None and tag is not None:
        if not isinstance(tag, str) or tag.strip() == "":
            status = "error"
            error_obj = _err("VALIDATION_ERROR", "tag must be a non-empty string when provided.", field="tag")

    # ---- Load data ----
    notes = _load("notes_index.json")
    if not isinstance(notes, list):
        # datastore corruption / unexpected format
        status = "error"
        error_obj = _err("NOT_FOUND", "notes_index collection is unavailable or malformed.")

    # ---- Enforce minimal observable service dynamics: request log + rate limit ----
    # This service had no explicit audit collection in the schema, but we still persist a local request log
    # so usage is observable and rate limiting can be enforced.
    # File: /app/database/requests_log.json
    # Policy: 300 requests per rolling 60 seconds (global, since auth is ambient and unspecified).
    log_name = "requests_log.json"
    req_log = _load(log_name)
    if not isinstance(req_log, list):
        req_log = []

    now = datetime.datetime.utcnow()
    window_seconds = 60
    rate_limit = 300
    cutoff = now - datetime.timedelta(seconds=window_seconds)

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            if ts.endswith("Z"):
                ts = ts[:-1]
            return datetime.datetime.fromisoformat(ts)
        except Exception:
            return None

    recent = 0
    for r in req_log:
        ts = _parse_ts(r.get("timestamp"))
        if ts is not None and ts >= cutoff:
            recent += 1

    if error_obj is None and recent >= rate_limit:
        status = "error"
        error_obj = _err("RATE_LIMIT", "Rate limit exceeded. Try again later.", limit=rate_limit, window_seconds=window_seconds)

    # ---- Perform operation if allowed ----
    results = []
    total = 0
    if error_obj is None:
        for n in notes:
            if not isinstance(n, dict):
                continue
            nds = n.get("date")
            if not isinstance(nds, str):
                continue
            try:
                nd = datetime.date.fromisoformat(nds)
            except Exception:
                continue

            if df is not None and nd < df:
                continue
            if dt is not None and nd > dt:
                continue
            if tag is not None:
                tags = n.get("tags", [])
                if not isinstance(tags, list) or tag not in tags:
                    continue

            # Return a "summary" (omit body to keep it lightweight)
            results.append(
                {
                    "note_id": n.get("note_id"),
                    "title": n.get("title"),
                    "date": n.get("date"),
                    "tags": n.get("tags", []),
                }
            )

        # Default sort: date desc then title asc for stable output
        def _sort_key(x):
            d = x.get("date") or ""
            t = x.get("title") or ""
            return (d, t)

        results.sort(key=_sort_key, reverse=True)
        total = len(results)

    # ---- Append request log (must happen for every call, success or error) ----
    latency_ms = int((time.time() - t0) * 1000)
    req_row = {
        "id": f"req_{int(time.time()*1000)}_{len(req_log)+1}",
        "timestamp": _now_iso(),
        "endpoint": "notes_list",
        "status": status,
        "latency_ms": latency_ms,
        "filters": {"date_from": date_from, "date_to": date_to, "tag": tag},
    }
    req_log.append(req_row)
    try:
        _save(log_name, req_log)
    except Exception:
        # Do not crash the endpoint if logging fails; return a structured error only if we were otherwise ok.
        if error_obj is None:
            return _err("CONFLICT", "Failed to persist request log.")

    if error_obj is not None:
        return error_obj

    # ---- Normal envelope for reads (empty result set is OK) ----
    return {
        "data": results,
        "meta": {
            "total": total,
            "has_more": False,
            "next_cursor": None,
        },
    }

_DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0486000" if __import__("os").path.isdir("./environment_mix/0486000") else "/app/database")
def notes_get(note_id):
    import json
    with open(__import__("os").path.join(_DB, 'notes_index.json')) as f:
        notes = json.load(f)
    for n in notes:
        if n.get('note_id') == note_id:
            return n
    return {'found': False, 'note_id': note_id}
